function check() {
    var action = workflowData.getMetaDataMap().get("actionTakenByAppropriateApprover");
    var action2 = workflowData.getMetaDataMap().get("actionTakenByAppropriateReqApprover");
    if (action != null && action != "") {
        if (action == "Send Back to Appropriate Requestor") {
            log.info("true");
            return true;
        } else {
            return false;
        }
    } else if (action2 != null && action2 != "") {
        if (action2 == "Send Back to Appropriate Requestor") {
            log.info("true");
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

or.script2:
function check() {
    var action = workflowData.getMetaDataMap().get("actionTakenByAppropriateApprover");
    var action2 = workflowData.getMetaDataMap().get("actionTakenByAppropriateReqApprover");
	var flagVal = workflowData.getMetaDataMap().get("AppropriateApproverFlag");
    if (action != null && action != "") {
        if (action == "Approve") {
            log.info("true");
            return true;
        } else {
            return false;
        }
    } else if (action2 != null && action2 != "") {
        if (action2 == "Approve") {
            log.info("true");
            return true;
        } else {
            return false;
        }
    } else if (flagVal == "false"){
	    return true;
	} else {
        return false;
    }
}

